(()=>{'use strict';const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),roman=['I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII'];let last=null;
function data(){let period;try{const current=KPTransit.currentPeriods();period={ready:true,periods:['MD','AD','PD'].map(level=>({level,id:current.periods[level].id,start:new Date(current.periods[level].startMs).toISOString().slice(0,19),end:new Date(current.periods[level].endMs).toISOString().slice(0,19)}))};}catch(e){return {ready:false,reason:e.message,hits:[],remedies:[]};}return KPHitMath.analyze(currentKPModel,period,{level:$('hit-level')?.value||'all',type:$('hit-type')?.value||'all',kind:$('hit-kind')?.value||'all',stars:$('hit-stars')?.checked!==false});}
function table(rows){return '<div class="hit-table-wrap"><table class="hit-table"><thead><tr><th>Hit</th><th>Active planet</th><th>Connection</th><th>Aspect / orb</th><th>Result</th><th>Directions</th></tr></thead><tbody>'+rows.map(h=>'<tr data-hit-kind="'+h.kind+'"><td>'+esc(h.type==='planet'?'Planet → active planet':h.type==='house'?'Active planet → cusp':'Active planet → house lord')+'</td><td><span>'+esc(h.active)+'</span><small>'+h.roles.map(r=>'<span>'+esc(r)+'</span>').join(' · ')+'</small></td><td><span>'+esc(h.from)+'</span> → <span>'+esc(h.target.startsWith('Cusp ')?roman[h.house-1]:h.target)+'</span>'+(h.house&&h.type!=='house'?' · '+roman[h.house-1]:'')+'</td><td>'+h.angle+'° · '+h.offset.toFixed(3)+'°</td><td><b>'+esc(h.kind==='positive'?'Supportive hit':'Adverse hit')+'</b><small>'+esc(h.effect)+'</small></td><td><span>'+esc(h.fromDirection.text)+'</span><small>'+esc(h.fromDirection.zones)+'</small> → <span>'+esc(h.targetDirection.text)+'</span><small>'+esc(h.targetDirection.zones)+'</small></td></tr>').join('')+'</tbody></table></div>';}
function remedies(rows){return rows.length?'<div class="hit-remedy-grid">'+rows.map(r=>'<article class="hit-remedy"><h3>'+esc(r.planet)+'</h3><p><b>Review directions:</b> <span>'+esc(r.fromDirection.text)+'</span> ('+esc(r.fromDirection.zones)+') / <span>'+esc(r.targetDirection.text)+'</span> ('+esc(r.targetDirection.zones)+')</p><p><b>Movable symbolic items:</b> '+r.items.map(i=>'<span>'+esc(i)+'</span>').join(', ')+'</p><p>Review these items in the affected directions and consider moving nonessential decorations to a supportive direction.</p><p><b>Supportive directions:</b> '+r.positiveDirections.map(d=>'<span>'+esc(d.text)+'</span> ('+esc(d.zones)+')').join(' · ')+'</p><p><b>Deity:</b> <span>'+esc(r.deity)+'</span> · <b>Vishnu avatar:</b> <span>'+esc(r.avatar)+'</span></p><details><summary>Botanical association</summary><p><span>'+esc(r.herb)+'</span></p><p>No safe use or dosage is supplied. Do not ingest or apply herbs. Datura is toxic.</p></details></article>').join('')+'</div>':'<p>No adverse hits match the selected native period and filters.</p>';}
function refresh(){last=data();const mount=$('hit-results');if(!mount)return last;if(!last.ready){mount.textContent=last.reason;return last;}const count=last.hits.length;$('hit-status').innerHTML=count+' <span>matching hits</span> · '+last.hits.filter(h=>h.kind==='negative').length+' <span>adverse</span>'; $('hit-current').innerHTML=last.periods.map(p=>'<span><b>'+esc(p.level)+'</b> · <span>'+esc(p.id)+'</span></span>').join('');mount.innerHTML=count?table(last.hits):'<p>No hits match the selected native period and filters.</p>';$('hit-remedies').innerHTML=remedies(last.remedies);return last;}
function snapshot(){const d=refresh();return '<div class="hit-report"><h2>HIT Theory · Native DBA</h2><p data-no-localize>'+esc($('name').value)+'</p>'+(!d.ready?'<p>'+esc(d.reason)+'</p>':'<p>'+d.periods.map(p=>'<b>'+esc(p.level)+'</b> · <span>'+esc(p.id)+'</span> · '+esc(p.start)+' → '+esc(p.end)).join('<br>')+'</p>'+table(d.hits)+'<h2>HIT Remedies</h2>'+remedies(d.remedies)+'<p>HIT aspects are astrological associations, not a diagnosis or a guaranteed event.</p>')+'</div>';}
function report(){const mount=$('printReport');mount.querySelectorAll('[data-report-section="hit-theory"]').forEach(p=>p.remove());const section=document.createElement('section');section.className='report-page hit-report-page';section.dataset.reportSection='hit-theory';section.innerHTML='<h2 class="report-page-title">HIT Theory and remedies</h2>'+snapshot();mount.append(section);}
function init(){const root=$('hit-theory');root.innerHTML='<article class="hit-window"><header><h2>HIT Theory</h2><button id="hit-theory-preview" type="button">Preview · Print / Save PDF</button></header><div class="hit-toolbar"><label>Period<select id="hit-level"><option value="all">MD / AD / PD</option><option value="MD">MD</option><option value="AD">AD</option><option value="PD">PD</option></select></label><label>Hit type<select id="hit-type"><option value="all">All hits</option><option value="planet">Planet → active planet</option><option value="house">Active planet → cusp</option><option value="lord">Active planet → house lord</option></select></label><label>Result<select id="hit-kind"><option value="all">All</option><option value="positive">Supportive hit</option><option value="negative">Adverse hit</option></select></label><button id="hit-calculate" type="button">Calculate</button><div id="hit-current"></div></div><p id="hit-status" role="status"></p><div id="hit-results"></div><details class="hit-remedies-panel"><summary>HIT Remedies</summary><div id="hit-remedies"></div></details><details><summary>Calculation details</summary><label><input id="hit-stars" type="checkbox" checked>Include active lords’ nakshatra lords</label><p>Supportive: 30° ±3°, 60° ±5°, 120° ±8°. Adverse: 45° ±3°, 90° ±5°, 180° ±8°. Positions use the native kundali; timing uses its current MD, AD and PD. Star-lord hits are shown first. Directions follow the HIT rashi map.</p></details></article>';
root.addEventListener('change',refresh);$('hit-calculate').addEventListener('click',()=>{refresh();renderReport();});$('hit-theory-preview').addEventListener('click',()=>KPReportPreview.open('hit-theory'));const old=window.renderReport;window.renderReport=function(...args){const result=old.apply(this,args);report();return result;};new MutationObserver(()=>{if(root.classList.contains('active'))refresh();}).observe(root,{attributes:true,attributeFilter:['class']});window.addEventListener('kp-preferences-changed',refresh);refresh();renderReport();KPReportPages.refresh();}
window.KPHit=Object.freeze({refresh,snapshot,getData:()=>structuredClone(data())});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(init,0));else init();})();
